8	/** The Sphinx card: "1 point. 2 per type beyond three, else 1." */
9	const BASE_POINTS = 1;
10	const FREE_TYPES = 3;
11	const POINTS_PER_TYPE_BEYOND_FREE = 2;
12	const POINTS_WITHIN_FREE_TYPES = 1;
13	
14	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
15	
16	const countDistinctTypes = (army: Card[]): number =>
17	  new Set(army.map((card) => card.monster)).size;
18	
19	const typeBonus = (distinctTypes: number): number =>
20	  distinctTypes > FREE_TYPES
21	    ? POINTS_PER_TYPE_BEYOND_FREE * (distinctTypes - FREE_TYPES)
22	    : POINTS_WITHIN_FREE_TYPES;
23	
24	/** Each Sphinx surveys the types around it — every card in the army but itself. */
25	const everyCardBut = (army: Card[], excludedIndex: number): Card[] => [
26	  ...army.slice(0, excludedIndex),
27	  ...army.slice(excludedIndex + 1),
28	];
29	
30	const scoreSphinxAt = (army: Card[], sphinxIndex: number): number =>
31	  BASE_POINTS + typeBonus(countDistinctTypes(everyCardBut(army, sphinxIndex)));
32	
33	export const scoreArmy = (army: Card[]): number =>
34	  army.reduce(
35	    (total, card, index) =>
36	      isSphinx(card) ? total + scoreSphinxAt(army, index) : total,
37	    0,
38	  );
