/** Each Sphinx surveys the types around it — every card in the army but itself. */
const cardsSurrounding = (sphinx: Card, army: Card[]): Card[] =>
  army.filter((card) => card !== sphinx);

const scoreSphinx = (sphinx: Card, army: Card[]): number =>
  BASE_POINTS + typeBonus(countDistinctTypes(cardsSurrounding(sphinx, army)));

export const scoreArmy = (army: Card[]): number =>
  army
    .filter(isSphinx)
    .reduce((total, sphinx) => total + scoreSphinx(sphinx, army), 0);

